import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';

interface StatsCardProps {
  title: string;
  type: 'progress' | 'donut';
  data: {
    label: string;
    value: number | string;
    subLabel: string;
    subValue: number | string;
  };
  color: string;
}

export const StatsCard: React.FC<StatsCardProps> = ({ title, type, data, color }) => {
  // Mock data for visualizations
  const chartData = [
    { name: 'Active', value: 75 },
    { name: 'Remaining', value: 25 },
  ];

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow duration-300">
      <h3 className="text-sm font-semibold text-slate-800 mb-6">{title}</h3>

      <div className="flex items-center gap-6">
        {/* Visualization Area */}
        <div className="relative w-28 h-28 flex-shrink-0">
            {type === 'donut' ? (
                <div className="w-full h-full relative">
                    <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                        data={chartData}
                        innerRadius={38}
                        outerRadius={50}
                        paddingAngle={0}
                        dataKey="value"
                        startAngle={90}
                        endAngle={-270}
                        stroke="none"
                        >
                        <Cell key="cell-0" fill={color} />
                        <Cell key="cell-1" fill="#f1f5f9" />
                        </Pie>
                    </PieChart>
                    </ResponsiveContainer>
                </div>
            ) : (
                <div className="w-full h-full flex flex-col justify-center gap-2">
                    <div className="w-full h-3 bg-slate-100 rounded-full overflow-hidden">
                        <div className="h-full rounded-full" style={{ width: '70%', backgroundColor: color }}></div>
                    </div>
                </div>
            )}
        </div>

        {/* Legend / Data Area */}
        <div className="flex-1 space-y-4">
            <div className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: color }}></span>
                <span className="text-xs text-slate-500">{data.label}</span>
                <span className="ml-auto font-bold text-slate-900 text-lg">{data.value}</span>
            </div>
            <div className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full bg-pink-300"></span>
                <span className="text-xs text-slate-500">{data.subLabel}</span>
                <span className="ml-auto font-bold text-slate-900 text-lg">{data.subValue}</span>
            </div>
        </div>
      </div>
    </div>
  );
};

